#!/bin/bash

############################################################################################
##
## Intune script — full Apeos printer stack in one go:
##   1. Add the four school copier queues via lpadmin
##   2. Deploy the captured preset template plist to all users + the User Template
##   3. Build /Applications/Update Printer Details.app for teachers to set their
##      own name + accounting code
##
## Assumes the Fujifilm Apeos driver pkg has been deployed via Intune LOB app.
## All steps are idempotent — safe to run daily. If the driver isn't present yet,
## step 1 fails (the script exits non-zero), Intune retries, and it converges.
##
############################################################################################

appname="ConfigurePrinters"
logandmetadir="/Library/Logs/Microsoft/IntuneScripts/$appname"
log="$logandmetadir/$appname.log"

[ -d "$logandmetadir" ] || mkdir -p "$logandmetadir"
exec &> >(tee -a "$log")

echo ""
echo "##############################################################"
echo "# $(date) | Starting $appname"
echo "##############################################################"
echo ""

############################################################################################
## STEP 1 — Install printer queues
############################################################################################

echo " $(date) | --- Step 1: install printer queues ---"

PPD_SRC="/Library/Printers/PPDs/Contents/Resources/FF Apeos C6570 PS.gz"
PPD_TMP="/tmp/apeos-c6570.ppd"

if [ ! -f "$PPD_SRC" ]; then
    echo " $(date) | ERROR: Apeos PPD not found at $PPD_SRC"
    echo " $(date) | Will exit non-zero so Intune retries once the driver pkg is in place."
    exit 1
fi

# Decompress PPD so lpadmin -P can use it directly (bypasses CUPS PPD lookup quirks)
gunzip -c "$PPD_SRC" > "$PPD_TMP"

QUEUES=(
    "Office_Copier|lpd://10.69.192.21/|Office Copier"
    "Ruru_Copier|lpd://10.69.192.23/|Ruru Copier"
    "Tui_Copier|lpd://10.69.192.24/|Tui Copier"
    "Nga_Rakau_e_Rua_Copier|lpd://10.69.192.25/|Nga Rakau e Rua Copier"
)
DEFAULT_QUEUE="Ruru_Copier"

for entry in "${QUEUES[@]}"; do
    IFS='|' read -r name uri desc <<< "$entry"
    echo " $(date) | Adding queue '$name' -> $uri"
    lpadmin -p "$name" -E -v "$uri" -P "$PPD_TMP" -D "$desc" -o printer-is-shared=false
    rc=$?
    if [ "$rc" -eq 0 ]; then
        echo " $(date) |   $name added"
    else
        echo " $(date) |   $name FAILED (exit $rc)"
    fi
done

rm -f "$PPD_TMP"

if lpstat -p "$DEFAULT_QUEUE" &>/dev/null; then
    lpoptions -d "$DEFAULT_QUEUE" &>/dev/null
    for home in /Users/*; do
        [ -d "$home/Library" ] || continue
        user=$(basename "$home")
        case "$user" in Shared|Guest|"Deleted Users"|.localized) continue ;; esac
        sudo -u "$user" lpoptions -d "$DEFAULT_QUEUE" &>/dev/null || true
    done
    echo " $(date) | Default queue set to $DEFAULT_QUEUE"
fi

############################################################################################
## STEP 2 — Deploy preset template plist
############################################################################################

echo ""
echo " $(date) | --- Step 2: deploy preset template ---"

PLIST_NAME="com.apple.print.custompresets.plist"
TEMPLATE="/tmp/${PLIST_NAME}.template"

base64 -D > "$TEMPLATE" << 'BASE64_EOF'

BASE64_EOF

if ! plutil -lint "$TEMPLATE" &>/dev/null; then
    echo " $(date) | ERROR: embedded preset template did not decode to a valid plist"
    rm -f "$TEMPLATE"
    exit 1
fi

SENTINEL_PRESET="Colour - Secure"

user_has_template() {
    local plist="$1"
    [ -f "$plist" ] && /usr/libexec/PlistBuddy -c "Print :${SENTINEL_PRESET}" "$plist" &>/dev/null
}

deploy_preset_to() {
    local target_pref_dir="$1" owner="$2"
    local target="$target_pref_dir/$PLIST_NAME"

    if user_has_template "$target"; then
        echo " $(date) |   already deployed at $target — skipping"
        return
    fi

    [ -d "$target_pref_dir" ] || mkdir -p "$target_pref_dir"
    cp "$TEMPLATE" "$target"
    chown "$owner" "$target"
    chmod 600 "$target"
    echo " $(date) |   deployed $target (owner $owner)"
}

deploy_preset_to "/Library/User Template/Non_localized/Library/Preferences" "root:wheel"

for home in /Users/*; do
    [ -d "$home/Library" ] || continue
    user=$(basename "$home")
    case "$user" in Shared|Guest|"Deleted Users"|.localized) continue ;; esac
    deploy_preset_to "$home/Library/Preferences" "$user:staff"
done

rm -f "$TEMPLATE"

############################################################################################
## STEP 3 — Build /Applications/Update Printer Details.app
############################################################################################

echo ""
echo " $(date) | --- Step 3: build Update Printer Details.app ---"

APP="/Applications/Update Printer Details.app"
rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS"
mkdir -p "$APP/Contents/Resources"

cat > "$APP/Contents/MacOS/UpdatePrinterDetails" << 'UPDATESCRIPT_EOF'
#!/bin/bash
set -e

PLIST="$HOME/Library/Preferences/com.apple.print.custompresets.plist"
PER_PRINTER_GLOB="$HOME/Library/Preferences/com.apple.print.custompresets.forprinter."*.plist

if [ "$EUID" -eq 0 ]; then
    echo "Run this as the logged-in user, not with sudo." >&2
    exit 1
fi

GUI_MODE=0
if [ ! -t 0 ] && [ ! -t 1 ]; then
    GUI_MODE=1
fi

gui_prompt() {
    osascript <<APPLESCRIPT 2>/dev/null
try
    set theResult to text returned of (display dialog "$1" default answer "" with title "Update Printer Details" with icon note)
    return theResult
on error number -128
    return ""
end try
APPLESCRIPT
}

gui_info() {
    osascript -e "display dialog \"$1\" buttons {\"OK\"} default button \"OK\" with title \"Update Printer Details\" with icon note" &>/dev/null
}

gui_error() {
    osascript -e "display dialog \"$1\" buttons {\"OK\"} default button \"OK\" with title \"Update Printer Details\" with icon stop" &>/dev/null
}

fail() {
    if [ "$GUI_MODE" -eq 1 ]; then
        gui_error "$1"
    else
        echo "$1" >&2
    fi
    exit 1
}

if [ ! -f "$PLIST" ]; then
    fail "No printer presets found yet. Make sure the Apeos printers are installed before running this."
fi

TEACHER_NAME=""
ACCOUNT_CODE=""

if [ "$GUI_MODE" -eq 1 ]; then
    TEACHER_NAME=$(gui_prompt "Enter your teacher name (as it should appear on the printer's secure-print release screen):")
    ACCOUNT_CODE=$(gui_prompt "Enter your accounting code:")
else
    read -r -p "Teacher name (leave blank to skip): " TEACHER_NAME
    read -r -p "Accounting code (leave blank to skip): " ACCOUNT_CODE
fi

if [ -z "$TEACHER_NAME" ] && [ -z "$ACCOUNT_CODE" ]; then
    if [ "$GUI_MODE" -eq 1 ]; then
        gui_info "No values entered — nothing to update."
    else
        echo "Nothing to update."
    fi
    exit 0
fi

killall cfprefsd 2>/dev/null || true
sleep 1

PRESETS=$(/usr/libexec/PlistBuddy -c "Print" "$PLIST" \
    | awk -F' = ' '/^    [^ ].* = Dict \{/ {sub(/^    /,""); sub(/ = Dict \{$/,""); print}')

if [ -z "$PRESETS" ]; then
    fail "No presets found in $PLIST"
fi

DOTTED_SETTINGS='com\.apple\.print\.preset\.settings'
KEY_PREFIX='com\.fujifilm\.fb\.jt\.printsettings\.ps\.ap'

set_key_at() {
    local file="$1" base_path="$2" key="$3" value="$4"
    local path="${base_path}.${KEY_PREFIX}\.${key}"
    if plutil -extract "$path" raw "$file" &>/dev/null; then
        plutil -replace "$path" -string "$value" "$file"
        return 0
    fi
    return 1
}

apply_at() {
    local file="$1" base_path="$2"
    local set_any
    if [ -n "$TEACHER_NAME" ]; then
        set_any=0
        for KEY in PrintTypeUserNameReference PrintTypeUserNameTicketKey; do
            if set_key_at "$file" "$base_path" "$KEY" "$TEACHER_NAME"; then
                set_any=1
            fi
        done
    fi
    if [ -n "$ACCOUNT_CODE" ]; then
        set_any=0
        for KEY in JBAUserIDTextEditReference JBAUserIDTextEditTicket; do
            if set_key_at "$file" "$base_path" "$KEY" "$ACCOUNT_CODE"; then
                set_any=1
            fi
        done
    fi
}

while IFS= read -r PRESET; do
    [ -z "$PRESET" ] && continue
    apply_at "$PLIST" "${PRESET}.${DOTTED_SETTINGS}"
done <<< "$PRESETS"

shopt -s nullglob
LAST_USED_PATH='com\.apple\.print\.v2\.lastUsedSettingsPref'
for pp_plist in $PER_PRINTER_GLOB; do
    plutil -extract "$LAST_USED_PATH" raw "$pp_plist" &>/dev/null || continue
    apply_at "$pp_plist" "$LAST_USED_PATH"
done
shopt -u nullglob

killall cfprefsd 2>/dev/null || true

if [ "$GUI_MODE" -eq 1 ]; then
    osascript -e "display dialog \"Printer details updated.\n\nA restart is required for the changes to appear in print dialogs. Restart now?\" buttons {\"Later\", \"Restart Now\"} default button \"Restart Now\" with title \"Update Printer Details\" with icon note" 2>/dev/null | grep -q "Restart Now" && osascript -e 'tell application "System Events" to restart'
else
    echo "Done. A reboot is required for the dialog to show the new values."
fi
UPDATESCRIPT_EOF

chmod +x "$APP/Contents/MacOS/UpdatePrinterDetails"

cat > "$APP/Contents/Info.plist" << 'PLIST_EOF'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleExecutable</key>
    <string>UpdatePrinterDetails</string>
    <key>CFBundleIdentifier</key>
    <string>nz.rangioraborough.printerupdater</string>
    <key>CFBundleName</key>
    <string>Update Printer Details</string>
    <key>CFBundleDisplayName</key>
    <string>Update Printer Details</string>
    <key>CFBundlePackageType</key>
    <string>APPL</string>
    <key>CFBundleShortVersionString</key>
    <string>1.0</string>
    <key>CFBundleVersion</key>
    <string>1</string>
    <key>LSMinimumSystemVersion</key>
    <string>10.15</string>
    <key>NSHighResolutionCapable</key>
    <true/>
</dict>
</plist>
PLIST_EOF

chown -R root:wheel "$APP"
echo " $(date) | Built $APP"

echo ""
echo " $(date) | $appname complete"
exit 0
